   [76]={next_id=77, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="一个带着粥的，温润甜香、还有点笨拙但异常坚定的吻。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT302_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [77]={next_id=78, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你被辉月这突如其来的动作搞得愣住了，手里的碗差点打翻。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT302_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
